import { Component, OnInit, HostListener, ElementRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { NavigationComponent } from '../../core/components/navigation.component';
import { ServiceApiService } from '../../core/services/service-api.service';
import { Service } from '../../core/models';

interface ServiceCategory {
  name: string;
  key: string;
  icon: string;
  description: string;
  color: string;
}

@Component({
  selector: 'app-services',
  standalone: true,
  imports: [CommonModule, RouterLink, NavigationComponent, FormsModule],
  templateUrl: './services.component.html',
  styleUrls: ['./services.component.scss']
})
export class ServicesComponent implements OnInit {
  allServices: Service[] = [];
  filteredServices: Service[] = [];
  selectedCategory: string = 'ALL';
  isLoading: boolean = true;
  sortBy: string = 'popularity';
  viewMode: string = 'grid';
  selectedService: Service | null = null;
  showServiceModal: boolean = false;
  scrollProgress: number = 0;

  categories: ServiceCategory[] = [
    { name: 'All Services', key: 'ALL', icon: '✨', description: 'View all our luxury offerings', color: '#BDCDE6' },
    { name: 'Hair Services', key: 'HAIR', icon: '💇', description: 'Cuts, colors & styling', color: '#B2BABC' },
    { name: 'Nail Services', key: 'NAILS', icon: '💅', description: 'Manicures & pedicures', color: '#FAF3EE' },
    { name: 'Skin Care', key: 'SKIN', icon: '✨', description: 'Facials & treatments', color: '#BDCDE6' },
    { name: 'Makeup', key: 'MAKEUP', icon: '💄', description: 'Professional makeup artistry', color: '#B2BABC' },
    { name: 'Spa & Massage', key: 'SPA', icon: '💆', description: 'Relaxation & wellness', color: '#FAF3EE' },
    { name: 'Bridal Services', key: 'BRIDAL', icon: '👰', description: 'Complete bridal packages', color: '#BDCDE6' },
    { name: 'Premium Packages', key: 'PREMIUM_PACKAGE', icon: '👑', description: 'Ultimate luxury experiences', color: '#2C2B30' }
  ];

  priceRanges = [
    { label: 'All Prices', min: 0, max: Infinity },
    { label: 'Under ₹100', min: 0, max: 100 },
    { label: '₹100-300', min: 100, max: 300 },
    { label: '₹300-500', min: 300, max: 500 },
    { label: '₹500+', min: 500, max: Infinity }
  ];

  selectedPriceRange = this.priceRanges[0];

  constructor(
    private serviceApi: ServiceApiService,
    private elementRef: ElementRef,
    private router: Router
  ) {}

  @HostListener('window:scroll')
  onScroll(): void {
    const scrollHeight = document.documentElement.scrollHeight - window.innerHeight;
    this.scrollProgress = (window.scrollY / scrollHeight) * 100;
  }

  ngOnInit(): void {
    this.loadServices();
    this.initScrollAnimations();
  }

  scrollToCategory(categoryKey: string): void {
    this.selectedCategory = categoryKey;
    this.applyFilters();
    setTimeout(() => {
      const firstService = this.filteredServices[0];
      if (firstService) {
        const element = document.getElementById(`service-${firstService.category}`);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }
    }, 100);
  }

  loadServices(): void {
    this.isLoading = true;
    this.serviceApi.getAllServices(0, 100).subscribe({
      next: (services) => {
        console.log('Services loaded:', services);
        this.allServices = services;
        this.applyFilters();
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Error loading services:', error);
        this.isLoading = false;
        alert('Unable to load services. Please ensure the backend server is running on http://localhost:8080');
      }
    });
  }

  filterByCategory(categoryKey: string): void {
    this.selectedCategory = categoryKey;
    this.applyFilters();
    this.animateCategoryTransition();
  }

  private animateCategoryTransition(): void {
    const cards = this.elementRef.nativeElement.querySelectorAll('.service-card');
    cards.forEach((card: HTMLElement, index: number) => {
      card.style.animation = 'none';
      setTimeout(() => {
        card.style.animation = `liquidSlide 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55) ${index * 0.05}s forwards`;
      }, 10);
    });
  }

  getCardParallax(index: number): string {
    const offset = (this.scrollProgress * index * 3) / 100;
    return `translateY(${offset}px)`;
  }

  applyFilters(): void {
    let filtered = [...this.allServices];

    // Category filter
    if (this.selectedCategory !== 'ALL') {
      filtered = filtered.filter(s => s.category === this.selectedCategory);
    }

    // Price range filter
    if (this.selectedPriceRange.max !== Infinity || this.selectedPriceRange.min !== 0) {
      filtered = filtered.filter(
        s => s.price >= this.selectedPriceRange.min && s.price <= this.selectedPriceRange.max
      );
    }

    // Sorting
    switch (this.sortBy) {
      case 'popularity':
        filtered.sort((a, b) => (b.popularity || 0) - (a.popularity || 0));
        break;
      case 'price-low':
        filtered.sort((a, b) => a.price - b.price);
        break;
      case 'price-high':
        filtered.sort((a, b) => b.price - a.price);
        break;
      case 'duration':
        filtered.sort((a, b) => a.duration - b.duration);
        break;
      case 'rating':
        filtered.sort((a, b) => (b.averageRating || 0) - (a.averageRating || 0));
        break;
    }

    this.filteredServices = filtered;
  }

  changeSortOrder(sortType: string): void {
    this.sortBy = sortType;
    this.applyFilters();
  }

  changePriceRange(range: any): void {
    this.selectedPriceRange = range;
    this.applyFilters();
  }

  toggleViewMode(): void {
    this.viewMode = this.viewMode === 'grid' ? 'list' : 'grid';
  }

  getStarArray(rating: number): boolean[] {
    return Array(5).fill(false).map((_, i) => i < Math.round(rating));
  }

  getCategoryInfo(categoryKey: string): ServiceCategory {
    return this.categories.find(c => c.key === categoryKey) || this.categories[0];
  }

  formatDuration(minutes: number): string {
    if (minutes < 60) return `${minutes} min`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins === 0 ? `${hours}h` : `${hours}h ${mins}m`;
  }

  openServiceDetails(service: Service): void {
    this.selectedService = service;
    this.showServiceModal = true;
    document.body.style.overflow = 'hidden';
  }

  closeServiceModal(): void {
    this.showServiceModal = false;
    this.selectedService = null;
    document.body.style.overflow = 'auto';
  }

  bookService(service: Service): void {
    this.closeServiceModal();
    this.router.navigate(['/booking'], { queryParams: { service: service.name } });
  }

  private initScrollAnimations(): void {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1 }
    );

    setTimeout(() => {
      document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
    }, 100);
  }
}
<!-- Navigation -->
<app-navigation></app-navigation>

<!-- Dynamic Gradient Background Container -->
<div class="services-container">
  <!-- Animated Background -->
  <div class="dynamic-background"></div>
  <div class="floating-orbs">
    <div class="orb orb-1"></div>
    <div class="orb orb-2"></div>
    <div class="orb orb-3"></div>
  </div>

  <!-- Immersive Hero Section -->
  <section class="hero-immersive">
    <div class="container mx-auto px-4">
      <div class="text-center">
        <h1 class="hero-title">Luxury <span class="morphing-text">Services</span></h1>
        <p class="hero-subtitle">Experience Beauty Redefined</p>
      </div>
    </div>
  </section>

  <!-- Category Pills -->
  <section class="category-pills-section">
    <div class="container mx-auto px-4">
      <div class="pills-container">
        <button
          *ngFor="let category of categories"
          class="category-pill"
          [class.active]="selectedCategory === category.key"
          (click)="scrollToCategory(category.key)"
        >
          <span class="pill-icon">{{ category.icon }}</span>
          <span class="pill-label">{{ category.name }}</span>
        </button>
      </div>
    </div>
  </section>

  <!-- Controls Bar -->
  <section class="controls-bar glass-morphism">
    <div class="container mx-auto px-4 py-6">
      <div class="flex flex-wrap justify-between items-center gap-4">
        <select [(ngModel)]="sortBy" (change)="changeSortOrder(sortBy)" class="control-select">
          <option value="popularity">Most Popular</option>
          <option value="rating">Top Rated</option>
          <option value="price-low">Price: Low to High</option>
          <option value="price-high">Price: High to Low</option>
          <option value="duration">Duration</option>
        </select>

        <select [(ngModel)]="selectedPriceRange" (change)="changePriceRange(selectedPriceRange)" class="control-select">
          <option *ngFor="let range of priceRanges" [ngValue]="range">{{ range.label }}</option>
        </select>

        <div class="results-count">
          <span class="count-number">{{ filteredServices.length }}</span>
          <span class="count-label">Services</span>
        </div>
      </div>
    </div>
  </section>

  <!-- Loading State -->
  <section *ngIf="isLoading" class="py-20">
    <div class="morphing-loader"></div>
  </section>

  <!-- Service Cards -->
  <section *ngIf="!isLoading" class="services-grid">
    <div class="container mx-auto px-4">
      <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        <div
          *ngFor="let service of filteredServices; let i = index"
          class="service-card"
          [id]="'service-' + service.category"
          (click)="openServiceDetails(service)"
        >
          <div class="card-image-container">
            <img [src]="service.image" [alt]="service.name" class="card-image" />
            <div class="image-overlay"></div>
          </div>

          <div class="card-content">
            <div class="category-badge">{{ getCategoryInfo(service.category).icon }} {{ getCategoryInfo(service.category).name }}</div>
            <h3 class="service-title">{{ service.name }}</h3>
            <p class="service-description">{{ service.description }}</p>

            <div class="service-meta">
              <div class="meta-item">
                <span class="icon">⏱️</span>
                <span>{{ formatDuration(service.duration) }}</span>
              </div>
              <div class="meta-item">
                <span class="icon">⭐</span>
                <span>{{ service.averageRating }}</span>
              </div>
            </div>

            <div class="price-tag">
              <span class="price">₹{{ service.price }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- Service Detail Modal -->
  <div *ngIf="showServiceModal && selectedService" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm" (click)="closeServiceModal()">
    <div class="modal-content bg-white rounded-3xl max-w-4xl w-full max-h-90vh overflow-y-auto shadow-2xl" (click)="$event.stopPropagation()">
      <div class="relative">
        <img [src]="selectedService.image" [alt]="selectedService.name" class="w-full h-80 object-cover" />
        <button (click)="closeServiceModal()" class="absolute top-4 right-4 bg-white/90 backdrop-blur-sm p-3 rounded-full hover:bg-white transition-all">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>
      </div>

      <div class="p-8">
        <h2 class="text-4xl font-bold text-charcoal mb-4">{{ selectedService.name }}</h2>
        <p class="text-lg text-charcoal/70 mb-6">{{ selectedService.description }}</p>

        <div class="grid grid-cols-2 gap-4 mb-6">
          <div class="bg-porcelain p-4 rounded-xl">
            <div class="text-sm text-charcoal/60 mb-1">Duration</div>
            <div class="text-xl font-bold text-charcoal">{{ formatDuration(selectedService.duration) }}</div>
          </div>
          <div class="bg-porcelain p-4 rounded-xl">
            <div class="text-sm text-charcoal/60 mb-1">Price</div>
            <div class="text-xl font-bold text-charcoal">₹{{ selectedService.price }}</div>
          </div>
        </div>

        <button (click)="bookService(selectedService)" class="w-full py-4 bg-gradient-to-r from-misty-blue to-soft-grey text-white rounded-xl font-bold text-lg hover:shadow-xl transition-all">
          Book This Service
        </button>
      </div>
    </div>
  </div>
</div>
